  InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.RightStick));InputSystem.Update();ProductionCheck(ReadSmithInput()&&workshopCostInspect,"Controller right-stick click enters cost inspection");
  InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.DpadRight));InputSystem.Update();ProductionCheck(ReadSmithInput()&&workshopCostFocus==1&&smithMetal==3,"Ingredient navigation leaves the selected recipe unchanged");
  InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));InputSystem.Update();ProductionCheck(ReadSmithInput()&&city.craftedGear.Count==beforeInspect,"Inspecting costs cannot accidentally craft gear");
  InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();yield return CardScreenshot(Path.Combine(folder,"11-ingredient-tooltip.png"));ProductionCheck(workshopCostHoverName=="Cured leather"&&workshopCostHoverOwned==city.ResourceAmount(4,1),"Focused ingredient tooltip shows the exact finished material and owned stock");
  InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.East));InputSystem.Update();ProductionCheck(ReadSmithInput()&&!workshopCostInspect&&SmithScreenOpen,"B leaves ingredient inspection before closing the workshop");
