  InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();yield return CardScreenshot(Path.Combine(folder,"12-processing-tooltip.png"));ProductionCheck(workshopCostHoverName==WeaponRules.BarName(1)&&workshopCostHoverRequired==2,"Alloy recipe tooltip identifies its required finished bar");
